import React, { useState, useEffect } from 'react';
import './Jubilacion.css';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

const Jubilacion = () => {
    const [prophetData, setProphetData] = useState([]);
    const [armaData, setArmaData] = useState([]);
    const [loading, setLoading] = useState(true);
    const [showProphetPrediction, setShowProphetPrediction] = useState(false);
    const [showArmaPrediction, setShowArmaPrediction] = useState(false);

    // Nuevos estados para "Calcular A:"
    const [selectedMonths, setSelectedMonths] = useState(3); // Valor por defecto: 3 meses
    const [filteredProphetData, setFilteredProphetData] = useState([]);
    const [showFilteredPredictions, setShowFilteredPredictions] = useState(false);
    const [showCalcularA, setShowCalcularA] = useState(false);

    // Función genérica para obtener datos
    const fetchData = async (url, setData) => {
        try {
            const response = await fetch(url);
            const result = await response.json();
            
            const chartData = result.dates.map((date, index) => ({
                date: date,
                value: result.values[index] || null,
                prediction: null
            }));
            
            const predictionsData = result.predictions.map((prediction, index) => ({
                date: new Date(chartData[chartData.length - 1].date).setDate(new Date(chartData[chartData.length - 1].date).getDate() + index + 1),
                value: null,
                prediction
            })).map(item => ({
                ...item,
                date: new Date(item.date).toISOString().split('T')[0]
            }));
            
            setData([...chartData, ...predictionsData]);
        } catch (error) {
            console.error('Error fetching data:', error);
            alert('Ocurrió un error al cargar los datos. Por favor, inténtalo más tarde.');
        }
    };

    useEffect(() => {
        const fetchAllData = async () => {
            await Promise.all([
                fetchData('http://localhost:8000/prophet-predictions', setProphetData),
                fetchData('http://localhost:8000/arma-predictions', setArmaData)
            ]);
            setLoading(false);
        };
        fetchAllData();
    }, []);

    // Función para alternar la visibilidad de las predicciones de Prophet
    const toggleProphetPrediction = () => {
        setShowProphetPrediction(!showProphetPrediction);
    };

    // Función para alternar la visibilidad de las predicciones de ARMA
    const toggleArmaPrediction = () => {
        setShowArmaPrediction(!showArmaPrediction);
    };

    // Función para filtrar las predicciones según los meses seleccionados
    const filterProphetPredictions = () => {
        // Obtener la fecha actual
        const currentDate = new Date();

        // Calcular la fecha de inicio basada en los meses seleccionados
        const startDate = new Date();
        startDate.setMonth(currentDate.getMonth() - selectedMonths);

        // Filtrar las predicciones dentro del rango de fechas seleccionado
        const predictions = prophetData.filter(dataPoint => {
            if (dataPoint.prediction) {
                const dataDate = new Date(dataPoint.date);
                return dataDate >= startDate && dataDate <= currentDate;
            }
            return false;
        });

        // Agrupar las predicciones por mes
        const predictionsByMonth = predictions.reduce((acc, curr) => {
            const month = curr.date.substring(0, 7); // Formato 'YYYY-MM'
            if (!acc[month]) acc[month] = [];
            acc[month].push(curr);
            return acc;
        }, {});

        // Tomar los últimos 5 días de predicciones de cada mes
        const lastFiveDaysPredictions = Object.values(predictionsByMonth).flatMap(monthPredictions => {
            return monthPredictions.slice(-5);
        });

        setFilteredProphetData(lastFiveDaysPredictions);
        setShowFilteredPredictions(true);
    };

    return (
        <div className="jubilacion-container">
            <h1 className="jubilacion-title">Predicción de Moneda</h1>
            <div className="jubilacion-content">
                <p>Este gráfico muestra el precio del dólar frente al peso mexicano (MXN) y las predicciones de los modelos Prophet y ARMA.</p>

                {loading ? (
                    <p>Cargando datos...</p>
                ) : (
                    <>
                        {/* Botones para Prophet y ARMA */}
                        <button onClick={toggleProphetPrediction} aria-label="Alternar predicción de Prophet">
                            {showProphetPrediction ? 'Ocultar predicción de Prophet' : 'Mostrar predicción de Prophet'}
                        </button>

                        <button onClick={toggleArmaPrediction} aria-label="Alternar predicción de ARMA">
                            {showArmaPrediction ? 'Ocultar predicción de ARMA' : 'Mostrar predicción de ARMA'}
                        </button>

                        {/* Botón y selector para "Calcular A:" */}
                        <div className="calcular-a-container">
                            <button onClick={() => setShowCalcularA(!showCalcularA)} aria-label="Mostrar opciones para Calcular A:">
                                Calcular A:
                            </button>
                            {showCalcularA && (
                                <div className="selector-meses">
                                    <label htmlFor="meses-select">Selecciona meses:</label>
                                    <select
                                        id="meses-select"
                                        value={selectedMonths}
                                        onChange={(e) => setSelectedMonths(Number(e.target.value))}
                                    >
                                        <option value={3}>3 Meses</option>
                                        <option value={4}>4 Meses</option>
                                        <option value={5}>5 Meses</option>
                                        <option value={6}>6 Meses</option>
                                    </select>
                                    <button onClick={filterProphetPredictions}>Aplicar</button>
                                </div>
                            )}
                        </div>

                        <ResponsiveContainer width="100%" height={400}>
                            <LineChart data={showFilteredPredictions ? filteredProphetData : prophetData}>
                                <CartesianGrid strokeDasharray="3 3" />
                                <XAxis dataKey="date" />
                                <YAxis />
                                <Tooltip />
                                {/* Línea para los datos reales de Prophet */}
                                <Line type="monotone" dataKey="value" stroke="#007bff" />
                                {/* Línea para las predicciones de Prophet, solo si se activa */}
                                {showProphetPrediction && (
                                    <Line type="monotone" dataKey="prediction" stroke="#ff0000" />
                                )}
                                {/* Línea para las predicciones filtradas de Calcular A: */}
                                {showFilteredPredictions && (
                                    <Line type="monotone" dataKey="prediction" stroke="#00ff00" />
                                )}
                            </LineChart>
                        </ResponsiveContainer>

                        <ResponsiveContainer width="100%" height={400}>
                            <LineChart data={armaData}>
                                <CartesianGrid strokeDasharray="3 3" />
                                <XAxis dataKey="date" />
                                <YAxis />
                                <Tooltip />
                                {/* Línea para los datos reales de ARMA */}
                                <Line type="monotone" dataKey="value" stroke="#28a745" />
                                {/* Línea para las predicciones de ARMA, solo si se activa */}
                                {showArmaPrediction && (
                                    <Line type="monotone" dataKey="prediction" stroke="#ff8000" />
                                )}
                            </LineChart>
                        </ResponsiveContainer>
                    </>
                )}
            </div>
        </div>
    );
};

export default Jubilacion;
